import org.rabochaya.projects.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class RasterExportFileTests {
 static long count(Path dir)throws IOException{try(java.util.stream.Stream<Path> paths=Files.list(dir)){return paths.count();}}
 static int n;static void ck(boolean b){n++;if(!b)throw new AssertionError("atomic export "+n);}static byte[] sqlite(byte value)throws Exception{byte[] bytes=new byte[100];System.arraycopy("SQLite format 3\0".getBytes("US-ASCII"),0,bytes,0,16);bytes[90]=value;return bytes;}
 public static void main(String[] args)throws Exception{Path dir=Files.createTempDirectory("rk-export-test-");try{Path out=dir.resolve("previous.mbtiles");byte[] original="previous user export".getBytes("UTF-8");Files.write(out,original);boolean failed=false;try{RasterExportFile.replace(out.toFile(),tmp->{try(FileOutputStream f=new FileOutputStream(tmp)){f.write(new byte[200]);}throw new IOException("cancelled");});}catch(IOException e){failed=true;}ck(failed&&Arrays.equals(Files.readAllBytes(out),original));ck(count(dir)==1);failed=false;try{RasterExportFile.replace(out.toFile(),tmp->0);}catch(IOException e){failed=true;}ck(failed&&Arrays.equals(Files.readAllBytes(out),original));byte[] next=sqlite((byte)7);int count=RasterExportFile.replace(out.toFile(),tmp->{try(FileOutputStream f=new FileOutputStream(tmp)){f.write(next);}return 12;});ck(count==12&&Arrays.equals(Files.readAllBytes(out),next));ck(count(dir)==1);Path absent=dir.resolve("new.mbtiles");failed=false;try{RasterExportFile.replace(absent.toFile(),tmp->{throw new IOException("no data");});}catch(IOException e){failed=true;}ck(failed&&!Files.exists(absent));Path folder=dir.resolve("folder");Files.createDirectory(folder);failed=false;try{RasterExportFile.replace(folder.toFile(),tmp->1);}catch(IOException e){failed=true;}ck(failed&&Files.isDirectory(folder));ck(Arrays.equals(Files.readAllBytes(out),next));failed=false;try{RasterExportFile.replace(out.toFile(),tmp->{try(RandomAccessFile f=new RandomAccessFile(tmp,"rw")){f.write(new byte[100]);f.setLength(512L*1024*1024+1);}return 1;});}catch(IOException e){failed=true;}ck(failed&&Arrays.equals(Files.readAllBytes(out),next));System.out.println("PASS RasterExportFile: "+n+" assertions");}finally{try(java.util.stream.Stream<Path> paths=Files.walk(dir)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(IOException e){throw new RuntimeException(e);}});}}}
}
